<script type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"ProfessionalService","@id":"https://utahinsuranceappraiser.com/#business","name":"Utah Insurance Appraiser","url":"https://utahinsuranceappraiser.com/","telephone":"+1 (844) 537-1427","email":"info@utahinsuranceappraiser.com","logo":{"@type":"ImageObject","@id":"https://utahinsuranceappraiser.com/#logo","url":"https://utahinsuranceappraiser.com/favicon-512.png","width":512,"height":512,"caption":"Utah Insurance Appraiser"},"image":{"@id":"https://utahinsuranceappraiser.com/#logo"},"address":{"@type":"PostalAddress","addressRegion":"UT","addressCountry":"US"},"contactPoint":[{"@type":"ContactPoint","telephone":"+1 (844) 537-1427","email":"info@utahinsuranceappraiser.com","contactType":"customer service","areaServed":"US-UT","availableLanguage":"en"}],"slogan":"Independent appraisal for underpaid Utah property claims","description":"Independent insurance appraisal, estimate review and umpire services for disputed property claims in all 29 Utah counties.","areaServed":[{"@type":"State","name":"Utah"},{"@type":"City","name":"Salt Lake City"},{"@type":"City","name":"West Valley City"},{"@type":"City","name":"Sandy"},{"@type":"City","name":"Provo"},{"@type":"City","name":"Orem"},{"@type":"City","name":"Lehi"},{"@type":"City","name":"Ogden"},{"@type":"City","name":"Layton"},{"@type":"City","name":"St. George"},{"@type":"City","name":"Logan"},{"@type":"City","name":"Park City"},{"@type":"City","name":"Cedar City"}],"hasOfferCatalog":{"@type":"OfferCatalog","@id":"https://utahinsuranceappraiser.com/#services","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Clause Representation","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/policy-appraisal-representation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Homeowner Claim Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/home-insurance-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/commercial-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/hail-roof-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wind & Tornado Damage Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/canyon-wind-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Snow Load, Ice Dam & Freeze Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/snow-ice-freeze-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water & Leak Damage Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/water-pipe-leak-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/fire-smoke-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wildfire Claim Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/wildfire-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Earthquake Claim Appraisal","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/earthquake-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/insurance-estimate-audit/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://utahinsuranceappraiser.com/utah-appraisal-services/appraisal-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Hail damage","Snow load","Wildfire claims","Earthquake endorsements"],"priceRange":"$$","openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://utahinsuranceappraiser.com/#website","url":"https://utahinsuranceappraiser.com/","name":"Utah Insurance Appraiser","publisher":{"@id":"https://utahinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://utahinsuranceappraiser.com/utah-appraisal-faq/#webpage","url":"https://utahinsuranceappraiser.com/utah-appraisal-faq/","name":"Utah Insurance Appraisal FAQ | Costs, Timing & Rules","description":"Answers to common Utah insurance appraisal questions, grouped by topic: how it works, costs, timing, Utah rules and when the award is binding.","inLanguage":"en-US","isPartOf":{"@id":"https://utahinsuranceappraiser.com/#website"},"about":{"@id":"https://utahinsuranceappraiser.com/#business"},"publisher":{"@id":"https://utahinsuranceappraiser.com/#business"},"dateModified":"2026-11-13","primaryImageOfPage":{"@type":"ImageObject","@id":"https://utahinsuranceappraiser.com/utah-appraisal-faq/#primaryimage","url":"https://utahinsuranceappraiser.com/assets/img/photos/living-room.webp","width":960,"height":640},"breadcrumb":{"@id":"https://utahinsuranceappraiser.com/utah-appraisal-faq/#breadcrumb"},"mainEntity":{"@id":"https://utahinsuranceappraiser.com/utah-appraisal-faq/#faq"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://utahinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal FAQ","item":"https://utahinsuranceappraiser.com/utah-appraisal-faq/"}],"@id":"https://utahinsuranceappraiser.com/utah-appraisal-faq/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is insurance appraisal?","acceptedAnswer":{"@type":"Answer","text":"A process in most property policies for resolving disagreements about the amount of a covered loss. Each side picks an appraiser, the appraisers pick an umpire, and any two can sign a binding award on the amount."}},{"@type":"Question","name":"Who can demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Either you or the insurer, in writing, when you disagree on the amount of loss. Check your policy for any steps that must come first."}},{"@type":"Question","name":"Is the award binding?","acceptedAnswer":{"@type":"Answer","text":"On the amount of loss, generally yes, once two of the three panel members sign. Courts can set awards aside in limited situations, such as fraud or a lack of impartiality."}},{"@type":"Question","name":"Does appraisal decide coverage?","acceptedAnswer":{"@type":"Answer","text":"No. It decides how much the covered damage costs. Disputes about whether something is covered are handled separately."}},{"@type":"Question","name":"How much does an appraiser cost?","acceptedAnswer":{"@type":"Answer","text":"Fee arrangements vary. Some appraisers charge hourly, some a flat fee and some a percentage of the increase. Each side pays its own appraiser and usually half of the umpire. Get terms in writing."}},{"@type":"Question","name":"How long does appraisal take?","acceptedAnswer":{"@type":"Answer","text":"Many residential appraisals finish within two to four months of both appraisers being named. Complex commercial claims can take longer."}},{"@type":"Question","name":"Is appraisal cheaper than a lawsuit?","acceptedAnswer":{"@type":"Answer","text":"Usually it’s faster and less expensive, because it focuses only on the amount of loss and avoids formal litigation. It also decides less."}},{"@type":"Question","name":"When is a gap too small for appraisal?","acceptedAnswer":{"@type":"Answer","text":"When fees would eat most of the expected increase. Our claim gap and fee estimator shows the math for your numbers."}},{"@type":"Question","name":"Who regulates insurance in Utah?","acceptedAnswer":{"@type":"Answer","text":"The Utah Insurance Department, led by the insurance commissioner. It licenses insurers, adjusters and public adjusters and accepts consumer complaints."}},{"@type":"Question","name":"Does Utah have a FAIR plan or wind pool?","acceptedAnswer":{"@type":"Answer","text":"Utah doesn’t operate a state FAIR plan or wind pool like some coastal states. Properties that standard carriers decline are typically placed in the surplus lines market. Ask your agent about options."}},{"@type":"Question","name":"How long do I have to sue my insurer in Utah?","acceptedAnswer":{"@type":"Answer","text":"Utah law generally allows three years from the inception of the loss for actions on first-party property policies. Confirm with a Utah attorney, especially if a deadline is close."}},{"@type":"Question","name":"What if I think my insurer acted in bad faith?","acceptedAnswer":{"@type":"Answer","text":"Utah generally treats an insurer’s duty of good faith to its own policyholder as part of the insurance contract, and the Insurance Code lists unfair claim settlement practices that the Insurance Department enforces. These are legal questions for a Utah attorney; appraisal doesn’t address them."}},{"@type":"Question","name":"Is earthquake damage covered in Utah?","acceptedAnswer":{"@type":"Answer","text":"Not under most standard homeowners policies. Earthquake coverage is usually an endorsement or separate policy with a percentage deductible."}},{"@type":"Question","name":"Do you work for the insurance company?","acceptedAnswer":{"@type":"Answer","text":"When we serve as your appraiser, we’re retained by you. When we serve as an umpire, we’re neutral and represent neither side."}},{"@type":"Question","name":"Are you a public adjuster or law firm?","acceptedAnswer":{"@type":"Answer","text":"No. We provide appraisal, estimating and umpire services. We don’t negotiate claims outside appraisal and don’t give legal advice."}},{"@type":"Question","name":"What areas of Utah do you serve?","acceptedAnswer":{"@type":"Answer","text":"All 29 counties, from Cache Valley to Washington County, including mountain and rural properties."}},{"@type":"Question","name":"What should I send for a free review?","acceptedAnswer":{"@type":"Answer","text":"The carrier’s full estimate, your declarations page, photos and any contractor estimate or correspondence."}}],"@id":"https://utahinsuranceappraiser.com/utah-appraisal-faq/#faq"}]}</script>
</head>
